<?php require_once __DIR__.'/../src/db.php';$id=(int)($_GET['id']??0);$q=db()->prepare("SELECT * FROM tours WHERE id=? AND published=1");$q->execute([$id]);$tour=$q->fetch();if(!$tour){http_response_code(404);exit('Tour not found');}$sql="SELECT s.*,p.image,p.title panorama_title FROM tour_scenes s JOIN panoramas p ON p.id=s.panorama_id WHERE s.tour_id=?";$args=[$id];if(!empty($tour['start_scene_id'])){$sql.=" AND s.id=?";$args[]=(int)$tour['start_scene_id'];}$sql.=" ORDER BY s.sort_order,s.id LIMIT 1";$q=db()->prepare($sql);$q->execute($args);$s=$q->fetch();if(!$s&&$tour['start_scene_id']){$q=db()->prepare("SELECT s.*,p.image,p.title panorama_title FROM tour_scenes s JOIN panoramas p ON p.id=s.panorama_id WHERE s.tour_id=? ORDER BY s.sort_order,s.id LIMIT 1");$q->execute([$id]);$s=$q->fetch();}if(!$s){http_response_code(404);exit('Tour has no scenes');}header('Location:/viewer.php?id='.$s['panorama_id'].'&tour='.$id.'&scene='.$s['id']);